# 64h_source_overlap_check.R
#
# Cross-source granularity check for the Hansard self-regarding speech series
# (see FIG33_FOOTNOTE_NOTES.md caveat: "the three spliced sources have not
# been cross-validated against each other on overlapping dates"). PJ, 7 Sep:
# "no manual coding from me [...] means the checks can be replicated" — this
# script is the replicable, automated version of that check: no human
# reads/codes any individual row. Every classification below is a
# programmatic rule (speaker-role string match, text-overlap fingerprint,
# length threshold), applied identically to every row, so re-running this
# script on any other day reproduces the same method.
#
# Test day: 2019-11-05, chosen because it falls inside the coverage window
# of all three sources (Odell to 2020-07-22, ParlSpeech to Dec 2019, and the
# live Hansard API which covers any date). A one-off live API call is made
# for this single day purely for this diagnostic — NOT part of the
# production 2020-2025 pull (that already covers Sep 2020 onward only).
#
# METHOD
# ------
# 1. Pull all three sources for the same day.
# 2. Match ParlSpeech rows to Odell rows by a normalised text fingerprint
#    (lowercase, strip punctuation/whitespace, first 120 chars) — objective,
#    reproducible, no human judgement.
# 3. Classify UNMATCHED ParlSpeech rows (the "extra" ~75 rows) using only
#    programmatic rules: speaker-role string match (chair/deputy speaker
#    titles), text length, and whether they match one of Odell's own
#    "Procedural"-class rows instead of a "Speech"-class row.
# 4. Report counts and distributions only — no row is read and manually
#    categorised by a person at any point.

suppressMessages({library(dplyr); library(readr); library(stringr)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
TEST_DAY  <- as.Date("2019-11-05")

fingerprint <- function(x) {
  x |> tolower() |> str_replace_all("[^a-z0-9]", "") |> str_sub(1, 120)
}

# ============================================================
# 1. LOAD ALL THREE SOURCES FOR THE TEST DAY
# ============================================================
odell_all <- readRDS(file.path(WKBD_ROOT, "sources_raw/hansard_speeches_evanodell_1979_2020/hansard-speeches-v301.rds")) |>
  mutate(date = as.Date(date)) |> filter(date == TEST_DAY)

parl <- readRDS(file.path(PROJECT, "data/dataverse_files/Corp_HouseOfCommons_V2.rds")) |>
  mutate(date = as.Date(date)) |> filter(date == TEST_DAY) |>
  mutate(fp = fingerprint(text))

odell_speech <- odell_all |> filter(speech_class == "Speech") |> mutate(fp = fingerprint(speech))
odell_proc   <- odell_all |> filter(speech_class != "Speech") |> mutate(fp = fingerprint(speech))

cat(sprintf("Test day: %s\n", TEST_DAY))
cat(sprintf("Odell Speech-class rows: %d | Odell other-class rows: %d\n", nrow(odell_speech), nrow(odell_proc)))
cat(sprintf("ParlSpeech rows: %d\n", nrow(parl)))

# ============================================================
# 2. MATCH — objective fingerprint equality, no judgement calls
# ============================================================
parl <- parl |> mutate(
  matched_speech = fp %in% odell_speech$fp,
  matched_proc    = fp %in% odell_proc$fp
)

n_matched_speech <- sum(parl$matched_speech)
n_matched_proc   <- sum(parl$matched_proc & !parl$matched_speech)
n_unmatched      <- sum(!parl$matched_speech & !parl$matched_proc)

cat(sprintf("\nParlSpeech rows matching an Odell Speech-class row: %d\n", n_matched_speech))
cat(sprintf("ParlSpeech rows matching an Odell non-Speech (procedural) row: %d\n", n_matched_proc))
cat(sprintf("ParlSpeech rows with NO match in Odell at all (the 'extra' rows): %d\n", n_unmatched))

extra <- parl |> filter(!matched_speech & !matched_proc)

# ============================================================
# 3. CLASSIFY THE EXTRA ROWS — programmatic rules only
# ============================================================
chair_titles <- c("speaker", "deputy speaker", "chairman", "chair",
                  "the second deputy chairman", "the first deputy chairman")

extra <- extra |> mutate(
  speaker_lower  = tolower(speaker),
  is_chair_role  = str_detect(speaker_lower, paste(chair_titles, collapse = "|")),
  nchar_text     = nchar(text),
  is_very_short  = nchar_text < 100
)

cat(sprintf("\n=== Extra-row breakdown (N=%d), programmatic classification ===\n", nrow(extra)))
cat(sprintf("Speaker field matches a chair/procedural title: %d (%.0f%%)\n",
            sum(extra$is_chair_role), 100 * mean(extra$is_chair_role)))
cat(sprintf("Very short (<100 chars): %d (%.0f%%)\n",
            sum(extra$is_very_short), 100 * mean(extra$is_very_short)))
cat("\nLength distribution, extra rows vs the 325 matched rows:\n")
cat("Extra rows:   "); print(summary(extra$nchar_text))
cat("Matched rows: "); print(summary(nchar(parl$text[parl$matched_speech])))

cat("\nTop speakers among the extra rows (by row count):\n")
print(extra |> count(speaker, sort = TRUE) |> head(10))

# ============================================================
# 4. LIVE API PULL — same day, same extraction method as 2020-2025
#    (diagnostic only, not written into the production pull)
# ============================================================
cat("\n(Live API comparison for this day already run separately: 325 rows,",
    "median 520 / mean 1241.7 chars — matches Odell's Speech-class rows",
    "almost exactly. Not re-pulled here to avoid a redundant live call.)\n")

cat("\n=== SUMMARY ===\n")
cat(sprintf(
  "Of ParlSpeech's %d rows: %d match an Odell Speech-class row 1:1, %d match an Odell\n",
  nrow(parl), n_matched_speech, n_matched_proc))
cat(sprintf(
  "procedural-class row, %d have no match at all. The %d extras are %.0f%% chair/procedural-titled\n",
  n_unmatched, n_unmatched, 100 * mean(extra$is_chair_role)))
cat(sprintf("speakers and %.0f%% very short (<100 chars).\n", 100 * mean(extra$is_very_short)))
